      log(`STOPPING on measured stall after ${bursts} bursts: ${stall.reason} (alongSum=${stall.alongSum.toFixed(3)} lateralSum=${stall.lateralSum.toFixed(3)} dist3dGain=${stall.dist3dGain.toFixed(3)})`);
