  const fail = (m) => { console.error(`[earned-continue-3d self-test] FAIL ${m}`); process.exit(1); };
  const dirs = { KeyW: [-0.87, 0.49], KeyS: [0.87, -0.49], KeyA: [-0.49, -0.87], KeyD: [0.49, 0.87] };
