const heavyLockFd = heavyLockFdRaw === null ? null : Number(heavyLockFdRaw);
const ACTIVE_ROLE = 'earned-continue-3d-runtime';
const role = arg('role', ACTIVE_ROLE);
const minSamples = Number(arg('min-samples', '4'));
